#!/usr/bin/env python3
"""
Simple validator for zimage-skill
"""

from pathlib import Path

def main():
    skill_dir = Path(__file__).parent
    errors = []

    # Check SKILL.md
    skill_md = skill_dir / "SKILL.md"
    if not skill_md.exists():
        errors.append("SKILL.md not found")
    else:
        content = skill_md.read_text()
        if "name:" not in content:
            errors.append("SKILL.md missing name field in frontmatter")
        if "description:" not in content:
            errors.append("SKILL.md missing description field in frontmatter")

    # Check scripts directory
    scripts_dir = skill_dir / "scripts"
    if not scripts_dir.exists():
        errors.append("scripts/ directory not found")
    else:
        generate_py = scripts_dir / "generate.py"
        if not generate_py.exists():
            errors.append("scripts/generate.py not found")
        else:
            # Check if generate.py has required functions
            content = generate_py.read_text()
            required_funcs = ['check_dependencies', 'get_api_key', 'create_task', 'wait_for_task', 'download_image']
            for func in required_funcs:
                if f"def {func}" not in content:
                    errors.append(f"generate.py missing {func} function")

        install_sh = scripts_dir / "install-deps.sh"
        if not install_sh.exists():
            errors.append("scripts/install-deps.sh not found")

    if errors:
        print("❌ Skill validation failed:")
        for error in errors:
            print(f"  - {error}")
        return False
    else:
        print("✅ Skill validation passed!")
        return True

if __name__ == "__main__":
    exit(0 if main() else 1)

